<?php
require_once __DIR__.'/includes/bootstrap.php';
if(empty($_SESSION['customer_id'])) { header('Location: customer_login.php'); exit; }
$q=$conn->prepare("SELECT a.booking_reference,a.appointment_date,a.appointment_time,a.status,a.cancellation_requested,s.service_name,s.price FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.customer_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC");$q->execute([$_SESSION['customer_id']]);$bookings=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My bookings | ELITE CUTS</title><link rel="stylesheet" href="css/style.css"><style>.my-wrap{width:min(1050px,92%);margin:65px auto 90px}.my-head{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:25px}.my-head h1{font:500 40px Georgia,serif;margin:8px 0}.booking-list{background:#fff;border:1px solid #eeece6;overflow-x:auto}.booking-list table{width:100%;border-collapse:collapse;min-width:650px}.booking-list th,.booking-list td{text-align:left;padding:17px;border-bottom:1px solid #eeece6;font-size:12px}.booking-list th{font-size:10px;letter-spacing:1px;color:#977747}.empty{background:#fff;padding:28px}.status{font-weight:700}.status-pending{color:#977747}.status-confirmed{color:#397b58}.status-cancelled{color:#a24e45}.request-note{display:block;color:#977747;font-size:11px;margin-top:6px}.request-btn{margin-top:8px;padding:8px 12px;border:1px solid #a24e45;background:#fff;color:#a24e45;cursor:pointer;font-size:11px}.request-btn:disabled{opacity:.55;cursor:not-allowed}</style></head><body><header class="site-header"><a class="brand" href="index.php"><span class="brand-mark">EC</span><span>ELITE <b>CUTS</b></span></a><nav class="site-nav"><a href="index.php">Home</a><a href="services.php">Services</a><a href="booking.php">Book a visit</a><a class="active" href="my_bookings.php">My bookings</a></nav><a class="header-cta" href="customer_logout.php">Log out ↗</a></header><main class="my-wrap"><div class="my-head"><div><p class="eyebrow">YOUR ELITE CUTS ACCOUNT</p><h1>My <em>appointments.</em></h1><p>Welcome, <?=h((string)$_SESSION['customer_name'])?>.</p></div><a class="button button-gold" href="booking.php">Book a visit ↗</a></div><?php if(!$bookings): ?><div class="empty">You haven't made any appointments yet. <a href="booking.php">Book your first visit.</a></div><?php else: ?><div class="booking-list"><table><thead><tr><th>REFERENCE</th><th>SERVICE</th><th>DATE &amp; TIME</th><th>TOTAL</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?=h($b['booking_reference'])?></td><td><?=h($b['service_name'])?></td><td><?=h(date('j M Y',strtotime($b['appointment_date'])))?> · <?=h(date('g:i A',strtotime($b['appointment_time'])))?></td><td>₦<?=number_format((float)$b['price'],2)?></td><td class="status status-<?=h(strtolower($b['status']))?>"><?=h($b['status'])?><?php if(!empty($b['cancellation_requested'])): ?><span class="request-note">Cancellation requested — awaiting admin decision</span><?php endif; ?></td><td><?php if(in_array($b['status'],['Pending','Confirmed'],true) && empty($b['cancellation_requested'])): ?><form method="post" action="customer_cancel_request.php" onsubmit="return confirm('Send a cancellation request to ELITE CUTS? Your appointment will remain active until the admin reviews it.');"><input type="hidden" name="reference" value="<?=h($b['booking_reference'])?>"><button class="request-btn" type="submit">Request cancellation</button></form><?php elseif(!empty($b['cancellation_requested'])): ?>Request sent<?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
